/* DÉREJ · El Pozo. Se integra en las pantallas existentes; no sustituye el patio. */
(()=>{
 'use strict';
 const C=window.DEREJ_POZO_CONTENT,screen=document.querySelector('[data-screen="pozo"]'),root=document.getElementById('pozoRoot');
 if(!C||!screen||!root)return;
 const KEY='derej.pozo.learning.v1',DAY=86400000;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
 const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const initial=()=>({version:1,discovered:false,settings:{large:false,contrast:false},seen:[],records:{},completed:{},memory:{completed:[],last:0},sessions:[],session:null});
 const alphabet='alfabeto';
 const L=id=>C.letters.find(l=>l.id===id),W=id=>C.words.find(w=>w.id===id);
 const ML=id=>C.memoryAlphabet.find(l=>l.id===id);
 const link=(id,label)=>`<button type="button" class="pzLink" data-pz="material:${esc(id)}">${esc(label)} · en Dérej</button>`;
 const btn=(label,action,alt='')=>`<button type="button" class="pzButton ${alt}" data-pz="${action}">${label}</button>`;
 const definitions=[
  {id:'alef-name',prompt:'¿Cómo se llama esta letra?',glyph:'א',options:['Álef','Vav','Resh','Mem'],correct:'Álef',hint:'Es la primera letra del alfabeto hebreo.',why:'א es álef. Su lectura depende de la vocalización y del contexto.',source:alphabet},
  {id:'resh-name',prompt:'¿Cómo se llama esta letra?',glyph:'ר',options:['Resh','Dálet','Yod','Mem'],correct:'Resh',hint:'Compárala con dálet: observa la esquina superior.',why:'ר es resh. Se distingue de ד, dálet, por la forma de su esquina superior.',source:alphabet},
  {id:'dalet-shape',prompt:'Busca dálet. Observa su esquina superior derecha.',options:['ד','ר','ו','י'],correct:'ד',glyphOptions:true,hint:'Busca un techo con un pequeño saliente en la esquina.',why:'ד es dálet; ר es resh. A veces un detalle pequeño cambia la letra.',source:alphabet},
  {id:'yod-shape',prompt:'Busca yod: el trazo pequeño y elevado.',options:['י','ו','ד','ר'],correct:'י',glyphOptions:true,hint:'No baja tanto como vav.',why:'י es yod. ו es vav y tiene un trazo vertical más largo.',source:alphabet},
  {id:'mem-final',prompt:'¿Qué forma toma mem al final de una palabra?',options:['ם','מ','ר','א'],correct:'ם',glyphOptions:true,hint:'La forma final de mem se cierra.',why:'Mem se escribe מ en su forma habitual y ם al final de palabra. Ambas conservan el sonido m.',source:alphabet},
  {id:'mem-relation',prompt:'¿Qué relación hay entre מ y ם?',options:['Son dos formas de mem','Son letras sin relación','Una es una vocal','Una es un signo de puntuación'],correct:'Son dos formas de mem',hint:'Piensa en la posición de la letra dentro de una palabra.',why:'Son formas de la misma letra: ם se utiliza al final de palabra. Puedes verlo en מַיִם.',source:alphabet},
  ...C.words.map(w=>({id:w.id+'-meaning',prompt:`¿Qué significa ${w.vocalized} en el pasaje de esta unidad?`,glyph:w.vocalized,options:w.id==='or'?['Luz','Agua','Tierra','Casa']:['Agua · aguas','Luz','Casa','Camino'],correct:w.meaning,hint:`Recuerda la palabra que practicamos: ${w.latin}.`,why:`${w.vocalized} se lee aproximadamente ${w.latin.toLowerCase()} y significa ${w.meaning.toLowerCase()}. ${w.grammar}`,source:w.source})),
  ...C.sages.map(s=>({id:'sage-'+s.id,prompt:`¿Qué nombre corresponde a ${s.name}?`,options:C.sages.map(x=>x.full),correct:s.full,hint:`En nuestros Caminos aparece junto a ${s.work}.`,why:`${s.name}: ${s.full}. ${s.context}`,source:s.source})),
  ...C.noaj.map((n,i)=>({id:'noaj-'+i,prompt:n.q,options:n.a,correct:n.a[0],hint:'Puedes volver al pasaje antes de responder.',why:n.why,source:n.source,ref:n.ref}))
 ];
 const Q=Object.fromEntries(definitions.map(q=>[q.id,q]));
 let data=initial(),storage=true,view='home',selectedLetter=0,selectedWord=0,lastResult=null,game=null,memoryTimer=null,voiceStatus='',materialId='alfabeto',materialBack='sources',traceStrokes=[],drawing=null,traceDrawingEnabled=true;
 try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.version===1){
  data.discovered=saved.discovered===true;
  data.settings={large:saved.settings?.large===true,contrast:saved.settings?.contrast===true};
  data.seen=Array.isArray(saved.seen)?saved.seen.filter(x=>C.letters.some(l=>l.id===x)):[];
  if(saved.records&&typeof saved.records==='object')for(const [id,r]of Object.entries(saved.records)){if(Q[id]&&r&&Number.isInteger(r.attempts)&&r.attempts>=0&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.attempts&&Array.isArray(r.days)&&r.days.every(d=>typeof d==='string')&&Number.isFinite(r.due))data.records[id]={attempts:r.attempts,correct:r.correct,days:r.days.slice(-30),lastCorrect:r.lastCorrect===true,due:r.due,lastAt:Number(r.lastAt)||0}}
  if(saved.completed&&typeof saved.completed==='object')for(const [id,c]of Object.entries(saved.completed)){if(['look','build','memory','trace','read','sages','noaj','daily'].includes(id)&&c&&Number.isFinite(c.at)&&Number.isInteger(c.count))data.completed[id]={at:c.at,count:c.count}}
  if(saved.memory&&typeof saved.memory==='object'){data.memory.completed=Array.isArray(saved.memory.completed)?[...new Set(saved.memory.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<C.memoryLevels.length))]:[];data.memory.last=Number.isInteger(saved.memory.last)&&saved.memory.last>=0&&saved.memory.last<C.memoryLevels.length?saved.memory.last:0}
  data.sessions=Array.isArray(saved.sessions)?saved.sessions.filter(s=>s&&Number.isFinite(s.at)&&typeof s.mode==='string').slice(-100):[];
  const s=saved.session;if(s&&['look','daily','sages','noaj'].includes(s.mode)&&Array.isArray(s.entries)&&s.entries.length&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.entries.length&&s.entries.every(e=>Q[e.id]&&Array.isArray(e.options)&&e.options.length===4&&new Set(e.options).size===4&&e.options.every(o=>Q[e.id].options.includes(o))&&(e.selected===null||e.options.includes(e.selected))))data.session={mode:s.mode,index:s.index,entries:s.entries.map(e=>({id:e.id,options:e.options,selected:e.selected,revealed:e.selected!==null,hint:e.hint===true}))};
 }localStorage.setItem(KEY,JSON.stringify(data))}catch{storage=false}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{storage=false;announce('El avance se conservará mientras esta página esté abierta. El navegador no permite guardarlo.')}}
 function announce(text){const el=document.getElementById('pzStatus');if(el)el.textContent=text}
 function seen(id){if(!data.seen.includes(id)){data.seen.push(id);save()}}
 function record(id,correct){const r=data.records[id]??{attempts:0,correct:0,days:[],due:0};r.attempts++;r.correct+=correct?1:0;r.lastCorrect=correct;r.lastAt=Date.now();if(correct&&!r.days.includes(today()))r.days.push(today());r.due=Date.now()+(correct?[1,3,7][Math.min(r.days.length-1,2)]*DAY:10*60000);data.records[id]=r;save()}
 function complete(mode,correct=null,total=null){const old=data.completed[mode];data.completed[mode]={at:Date.now(),count:(old?.count||0)+1};data.sessions.push({at:Date.now(),mode,correct,total});data.sessions=data.sessions.slice(-100);save()}
 const remembered=r=>r?.days.length>=3&&r.lastCorrect;
 function nav(){return `<nav class="pzNav" aria-label="Dentro del Pozo">${[['home','Mi taller'],['welcome','Primer encuentro'],['letters','Las letras'],['words','Las palabras'],['progress','Mi avance']].map(([id,label])=>`<button type="button" data-pz-view="${id}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`}
 function layout(html,{hero=false,title='El Pozo'}={}){
  screen.classList.toggle('pzLarge',data.settings.large);screen.classList.toggle('pzContrast',data.settings.contrast);
  root.innerHTML=`<div class="pzTop"><button class="backBtn" type="button" data-route="home">← Patio</button><span class="pzCrumb">EL POZO · DÉREJ</span><div class="pzTools"><button class="pzIcon" data-pz="large" aria-label="Ampliar texto" aria-pressed="${data.settings.large}">A+</button><button class="pzIcon" data-pz="contrast" aria-label="Aumentar contraste" aria-pressed="${data.settings.contrast}">◐</button></div></div><h1 class="pzSr" id="pozoTitle">El Pozo · ${esc(title)}</h1>${hero?`<header class="pzHero"><div><span class="pzEyebrow">APRENDER · RECORDAR · VOLVER A LA FUENTE</span><h2 style="font-size:3.4em;line-height:1.05;margin:10px 0">El Pozo.</h2><p>Hay palabras que empiezan a abrirse cuando aprendemos a mirarlas.</p></div></header>`:''}${data.discovered?nav():''}<div class="${view==='gate'?'pzGate':'pzMain'}" id="pzMain" tabindex="-1">${html}</div><div class="pzStatus" id="pzStatus" role="status" aria-live="polite"></div>`;
 }
 function open(next='home',focus=true){
  if(memoryTimer&&next!=='memory'){clearTimeout(memoryTimer);memoryTimer=null;if(game?.mode==='memory'){game.busy=false;game.open=[]}}
  if(drawing)drawing=null;
  view=data.discovered?next:'gate';
  if(view==='gate')gate();else if(view==='home')home();else if(view==='welcome')welcome();else if(view==='letters')letters();else if(view==='words')words();else if(view==='word')word();else if(view==='progress')progress();else if(view==='sources')sources();else if(view==='material')material();else if(view==='round')round();else if(view==='build')build();else if(view==='memory-levels')memoryLevels();else if(view==='memory-study')memoryStudy();else if(view==='memory-done')memoryDone();else if(view==='memory')memory();else if(view==='trace')trace();else if(view==='read')read();else if(view==='summary')summary();else if(view==='voices')voices();else home();
  screen.classList.toggle('pzTracing',view==='trace');
  if(focus){document.getElementById('pzMain')?.focus({preventScroll:true});screen.scrollIntoView({behavior:'instant',block:'start'})}
 }
 function gate(){layout(`<div class="pzDrop" aria-hidden="true">◉</div><span class="pzEyebrow">EL AGUA GUARDA UN ENCUENTRO</span><h2>Acércate.<br>Hay algo por descubrir.</h2><p>En el fondo del Pozo habitan letras, palabras y voces. Puedes reconocerlas, jugar con ellas y regresar al texto con una mirada nueva.</p><div class="pzActions">${btn('Descubrir el taller ↓','discover')}</div><p class="pzCaption">Para volver, busca la misma señal pequeña sobre el agua del patio.</p>`,{hero:true,title:'Descubrir'})}
 const activities=[['look','Mirar de cerca','Distingue letras y formas que se parecen.','6 encuentros'],['build','Construir una palabra','Letras que encuentran su lugar de derecha a izquierda.','2 palabras'],['memory','El espejo del recuerdo','Avanza hasta reconocer las 22 letras y sus cinco formas finales.','8 niveles'],['trace','Seguir el trazo','Observa una forma y dibuja sobre ella con el dedo.','Práctica libre'],['read','Dentro del pasaje','Encuentra la palabra que aprendiste en nuestros estudios.','2 pasajes'],['daily','Mi práctica de hoy','Vuelve a las conexiones que piden otro encuentro.','6 preguntas']];
 function home(){const done=activities.filter(([id])=>data.completed[id]).length;layout(`<article class="pzReadingBox"><span class="pzEyebrow">PARA COMENZAR · A SOLAS O EN COMUNIDAD</span><h2>Tu primer encuentro con el Pozo.</h2><p>Una letra, una palabra y una pregunta para compartir. Un recorrido de unos 10 minutos, a tu ritmo y sin examen.</p><div class="pzActions">${btn('Hacer el primer encuentro →','welcome')}</div><p class="pzCaption">Después puedes explorar los juegos, las voces y el relato de Nóaj. No hace falta hacerlo todo hoy.</p></article><article class="pzUnit"><div><span class="pzEyebrow">HEBREO BÍBLICO · UNIDAD 01</span><h2>Agua y luz.</h2><p>Del signo a la palabra. Seis letras, una forma final y dos palabras de los encuentros OR y RAKIA.</p><div class="pzActions">${btn(data.seen.length?'Volver a las letras →':'Comenzar por las letras →','letters')}</div></div><div class="pzUnitArt pzHeb" lang="he" aria-hidden="true">מים</div></article><div class="pzSectionHead"><h2>Aprender también es jugar</h2><span class="pzCaption">${done} de 6 explorados</span></div><div class="pzGrid">${activities.map(([id,title,desc,detail],i)=>`<button type="button" class="pzCard" data-pz="activity:${id}"><span class="pzCardNum">${String(i+1).padStart(2,'0')} · ${detail.toUpperCase()}</span><h3>${title}</h3><p>${desc}</p><span class="pzCardFoot"><span>${data.completed[id]?'Volver a practicar':'Entrar a descubrir'}</span><span aria-hidden="true">↗</span></span></button>`).join('')}</div><div class="pzSectionHead"><h2>Para seguir explorando</h2></div><div class="pzGrid"><button class="pzCard" data-pz="voices"><span class="pzCardNum">LOS SABIOS DE NUESTROS CAMINOS</span><h3>Detrás de un nombre</h3><p>Rambam, Ramak, Ramjal, Baal Shem Tov y Rabí Najmán: nombres, obras y conexiones.</p><span class="pzCardFoot">Explorar las voces <span>↗</span></span></button><button class="pzCard" data-pz="activity:noaj"><span class="pzCardNum">PARASHAT NÓAJ</span><h3>Huellas del relato</h3><p>Cuatro preguntas para volver al arca, al agua y al comienzo.</p><span class="pzCardFoot">Volver a Nóaj <span>↗</span></span></button></div><div class="pzNotice">Sin cronómetro ni rachas obligatorias. El avance refleja lo que practicas aquí; no mide tu capacidad cognitiva general.</div><div class="pzActions"><button class="pzTextButton" data-pz-view="sources">Nuestro material de estudio</button><button class="pzTextButton" data-pz-view="progress">Ver mi avance →</button></div><p class="pzCaption">${storage?'Tu avance se guarda en este navegador y dispositivo.':'El navegador no permite guardar tu avance; se conserva mientras esta página esté abierta.'}</p>`,{hero:true,title:'Taller de la Memoria'})}

 function welcome(){layout(`<span class="pzEyebrow">PRIMER ENCUENTRO · UNOS 10 MINUTOS</span><h2>Del agua a la palabra.</h2><p>Ya encontraste la entrada. Ahora vamos a mirar una letra, reconocer una palabra del texto y compartir lo que descubrimos. Puedes hacerlo a solas o junto a otra persona.</p><div class="pzNotice">No necesitas saber hebreo ni acertar a la primera. Aquí no hay cronómetro. Usa A+ para ampliar el texto. Si la voz no está disponible, puedes continuar leyendo.</div><ol class="pzFirstSteps"><li><h3>Mirar · 2 minutos</h3><p>Abre <b>mem, מ</b>. Observa su forma y su sonido m. Mira también <span class="pzHeb" lang="he">ם</span>: es la misma letra al final de una palabra. No hace falta memorizar sus valores numéricos hoy.</p><div class="pzActions">${btn('Observar mem →','welcome-letter')}</div></li><li><h3>Trazar · 2 minutos</h3><p>Sigue la sombra de <span class="pzHeb" lang="he">מ</span> con el dedo. Puedes deshacer, limpiar o simplemente observar. No buscamos caligrafía perfecta.</p><div class="pzActions">${btn('Trazar mem →','trace:'+C.letters.findIndex(l=>l.id==='mem'))}</div></li><li><h3>Reconocer · 3 minutos</h3><p><span class="pzHeb" lang="he">מַיִם</span>, <b>máyim</b>, significa agua o aguas. Se lee de derecha a izquierda: mem, yod, mem final. Abre la palabra y después búscala dentro de <span class="pzHeb" lang="he">הַמָּיִם</span>, las aguas, en Génesis 1:6.</p><div class="pzActions">${btn('Conocer máyim →','word:0')}${btn('Buscarla en el pasaje →','read-word:0','alt')}</div><p class="pzCaption">El segundo pasaje y la construcción de palabras son opcionales para este primer encuentro.</p></li><li><h3>Compartir · 3 minutos</h3><p>Sin mirar la ficha: ¿qué detalle te ayuda a reconocer mem? ¿Qué cambia cuando aparece al final de la palabra?</p><p><b>Para conversar:</b> al descubrir el Pozo, ¿qué te dio curiosidad? ¿Qué fue claro y en qué momento necesitaste ayuda? Puedes compartir o escuchar, sin obligación de responder.</p><p class="pzCaption">Si el agua te sugiere una imagen para tu vida, compártela como reflexión personal; no como traducción de las letras ni como una enseñanza atribuida a un sabio.</p></li></ol><article class="pzReadingBox"><h3>Por hoy, es suficiente.</h3><p>No buscamos terminar todos los juegos. Quédate con una forma, una palabra y una pregunta. Otro día puedes volver a reconocerlas sin mirar primero.</p><div class="pzActions">${btn('Ver mi avance →','progress')}${btn('Explorar el taller','home','alt')}</div><p class="pzCaption">El avance cuenta las actividades que guardas o terminas; abrir esta guía no registra una práctica completada. Se conserva en este navegador y dispositivo.</p></article><p class="pzCaption">Para regresar a esta guía desde una actividad, toca «Primer encuentro» en la barra del Pozo.</p>`,{title:'Primer encuentro'});}

 function voiceButton(id,text){return `<button class="pzButton alt" data-pz="speak:${id}">♫ ${text}</button><p class="pzSoundStatus" data-voice-status>${esc(voiceStatus||'Pronunciación sintetizada con la voz hebrea del dispositivo, cuando esté disponible.')}</p>`}
 function letters(){const l=C.letters[selectedLetter];seen(l.id);layout(`<span class="pzEyebrow">01 · MIRAR Y ESCUCHAR</span><h2>Una letra, un encuentro.</h2><p>Elige una forma. Mira su detalle y descubre cómo aparece en la palabra.</p><div class="pzLetterTabs" role="tablist" aria-label="Letras de esta unidad">${C.letters.map((x,i)=>`<button type="button" role="tab" data-pz="letter:${i}" aria-selected="${i===selectedLetter}" aria-controls="pzLetterPanel" id="pzLetterTab${i}"><span class="pzHeb" lang="he">${x.glyph}</span><small>${x.name}</small></button>`).join('')}</div><article class="pzLetterDetail" id="pzLetterPanel" role="tabpanel" aria-labelledby="pzLetterTab${selectedLetter}"><div class="pzLetterDetailHeader"><span class="pzHeb pzBigGlyph" lang="he">${l.glyph}</span><div><span class="pzEyebrow">${l.id==='mem-final'?'FORMA FINAL':'LETRA HEBREA'}</span><h2>${l.name}</h2><span class="pzCaption">Valor numérico: ${l.value}</span></div></div>${voiceButton(l.id,'Escuchar el nombre')}<h3>Su sonido</h3><p>${l.sound}</p><h3>Mira de cerca</h3><p>${l.look}</p><h3>Una conexión para recordar</h3><p>${l.note}</p>${link(alphabet,'Abrir la ficha del alfabeto')}<div class="pzActions">${btn('Trazar esta letra','trace:'+selectedLetter,'alt')}${btn(selectedLetter<C.letters.length-1?'Siguiente letra →':'Practicar las formas →',selectedLetter<C.letters.length-1?'letter:'+(selectedLetter+1):'activity:look')}</div></article><div class="pzNotice">Las letras representan sonidos y forman palabras. Sus valores numéricos y lecturas simbólicas son otros planos de estudio; no sustituyen la lectura ni la traducción.</div>`,{title:l.name});refreshVoices()}
 function words(){layout(`<span class="pzEyebrow">02 · DEL SIGNO A LA PALABRA</span><h2>Dos palabras de nuestros estudios.</h2><p>Mira cómo las letras se reúnen. Los puntos y trazos de vocalización te acompañan al empezar.</p><label class="pzToggle"><input type="checkbox" id="pzNikud" checked> Mostrar vocalización</label><div class="pzWordList">${C.words.map((w,i)=>`<article class="pzWord"><span class="pzEyebrow">${w.ref}</span><span class="pzHeb" lang="he" data-word-he="${i}">${w.vocalized}</span><h2>${w.latin}</h2><p>${w.meaning}</p><button class="pzButton alt" data-pz="word:${i}">Abrir la palabra →</button></article>`).join('')}</div><div class="pzNotice">La vocalización ayuda a leer. En un rollo de la Torá esos signos no se escriben; aquí puedes mostrarlos u ocultarlos para observar la diferencia.</div><div class="pzActions">${btn('Construir las palabras →','activity:build')}${btn('Encontrarlas en el pasaje','activity:read','alt')}</div>`,{title:'Las palabras'})}
 function word(){const w=C.words[selectedWord];layout(`<button class="pzTextButton" data-pz-view="words">← Las palabras</button><span class="pzEyebrow">${w.ref} · PALABRA EN CONTEXTO</span><article class="pzReadingBox"><span class="pzHeb" lang="he">${w.vocalized}</span><h2>${w.latin} · ${w.meaning}</h2>${voiceButton(w.id,'Escuchar la palabra')}<p>${w.grammar}</p><details><summary>¿Qué hacen los puntos y trazos?</summary><p>${w.vowelNote}</p></details><details><summary>Una reflexión de Dérej</summary><p>${w.symbol}</p></details></article><article class="pzReadingBox"><span class="pzEyebrow">VOLVER A LA FUENTE · ${w.ref}</span><span class="pzHeb" lang="he" style="font-size:2em">${w.passage.join(' ')}</span><p>${w.translation}</p><p>${w.context}</p>${link(w.source,'Abrir el pasaje de estudio')}</article><div class="pzActions">${btn('Construir esta palabra →','build-word:'+selectedWord)}${btn('Encontrarla en el texto','read-word:'+selectedWord,'alt')}</div>`,{title:w.latin});refreshVoices()}
 function startRound(mode){let pool=mode==='sages'?definitions.filter(q=>q.id.startsWith('sage-')):mode==='noaj'?definitions.filter(q=>q.id.startsWith('noaj-')):definitions.filter(q=>!q.id.startsWith('sage-')&&!q.id.startsWith('noaj-'));
  if(mode==='look')pool=pool.slice(0,6);else if(mode==='daily'){pool=shuffle(pool);const priority=q=>{const r=data.records[q.id];return r?.lastCorrect===false?0:r?.due<=Date.now()?1:!r?2:3};pool.sort((a,b)=>priority(a)-priority(b)||((data.records[a.id]?.due||0)-(data.records[b.id]?.due||0)));pool=pool.slice(0,6)}else pool=shuffle(pool);
  data.session={mode,index:0,entries:pool.map(q=>({id:q.id,options:shuffle(q.options),selected:null,revealed:false,hint:false}))};save();open('round')
 }
 function round(){const s=data.session;if(!s){open('home');return}const e=s.entries[s.index],q=Q[e.id],correct=e.selected===q.correct;
  layout(`<div class="pzRoundMeta"><button class="pzTextButton" data-pz="pause">← Guardar y volver</button><span>${s.index+1} / ${s.entries.length}</span></div><div class="pzProgressBar" style="--pz-progress:${(s.index+(e.revealed?1:0))/s.entries.length*100}%" role="progressbar" aria-label="Preguntas respondidas" aria-valuemin="0" aria-valuemax="${s.entries.length}" aria-valuenow="${s.index+(e.revealed?1:0)}"><span></span></div><article class="pzRound"><span class="pzEyebrow">${s.mode==='sages'?'VOCES DE DÉREJ':s.mode==='noaj'?'HUELLAS DE NÓAJ':'MIRAR · RECONOCER · RECORDAR'}</span><h2 id="pzQuestion">${esc(q.prompt)}</h2>${q.glyph?`<span class="pzHeb pzQuestionGlyph" lang="he">${q.glyph}</span>`:''}<div class="pzChoices" role="group" aria-labelledby="pzQuestion">${e.options.map((o,i)=>`<button class="pzChoice ${e.revealed&&o===q.correct?'correct':e.revealed&&o===e.selected?'wrong':''}" data-pz="answer:${i}" ${e.revealed?'disabled':''}><span class="pzOption" aria-hidden="true">${'ABCD'[i]}</span><span ${q.glyphOptions?'class="pzHeb" lang="he"':''}>${esc(o)}</span>${e.revealed&&o===q.correct?'<span class="pzSr">Respuesta correcta</span>':''}</button>`).join('')}</div>${e.revealed?`<div class="pzFeedback ${correct?'':'warm'}" tabindex="-1" id="pzFeedback" role="status"><b>${correct?'Una conexión que crece.':'Volvamos a mirar.'}</b><p>${correct?'':`La respuesta es ${esc(q.correct)}. `}${esc(q.why)}</p>${link(q.source,q.ref||'Ver la explicación de Dérej')}</div><div class="pzActions">${btn(s.index<s.entries.length-1?'Siguiente →':'Terminar esta práctica ✓','next')}</div>`:`<button class="pzTextButton" data-pz="hint" aria-expanded="${e.hint}">${e.hint?'Ocultar pista −':'Necesito una pista +'}</button>${e.hint?`<div class="pzNotice">${q.hint}</div>`:''}`}</article><p class="pzCaption">Sin cronómetro. Puedes volver a la ficha y retomar esta práctica después.</p>`,{title:'Mi práctica'})
 }
 function respond(index){const s=data.session,e=s?.entries[s.index];if(!e||e.revealed)return;const selected=e.options[index];if(selected===undefined)return;e.selected=selected;e.revealed=true;record(e.id,selected===Q[e.id].correct);save();round();document.getElementById('pzFeedback')?.focus()}
 function next(){const s=data.session;if(!s?.entries[s.index].revealed)return;if(s.index<s.entries.length-1){s.index++;save();open('round')}else{const correct=s.entries.filter(e=>e.selected===Q[e.id].correct).length;complete(s.mode,correct,s.entries.length);lastResult={mode:s.mode,correct,total:s.entries.length};data.session=null;save();open('summary')}}
 function summary(){if(!lastResult){open('home');return}layout(`<article class="pzSummary"><span class="pzEyebrow">UN ENCUENTRO MÁS</span><span class="pzHeb" lang="he" aria-hidden="true">מים · אור</span><h2>${lastResult.mode==='trace'?'Mirar también es aprender.':'Hoy hiciste una nueva conexión.'}</h2><p>${lastResult.correct!==null?`${lastResult.correct} de ${lastResult.total} conexiones reconocidas en esta práctica.`:lastResult.mode==='trace'?'Guardamos que practicaste el trazo. No calificamos tu escritura.':'Encontraste las parejas entre letras y nombres.'}</p><p>Volver en otro día ayuda a comprobar qué recuerdas. No necesitas completar todo de una vez.</p><div class="pzActions">${btn('Volver al primer encuentro','welcome')}${btn('Ver mi avance →','progress','alt')}${btn('Seguir explorando','home','alt')}</div></article>`,{title:'Encuentro completado'})}
 function startBuild(index=0){game={mode:'build',index,order:index===1?[1,0]:[0,1],step:0,slots:[],options:shuffle([...C.words[index].letters,'ד','ו']),feedback:false,wrong:false,correct:0,attempts:0};open('build')}
 function build(){if(game?.mode!=='build'){startBuild();return}const w=C.words[game.index];layout(`<button class="pzTextButton" data-pz="home">← Mi taller</button><span class="pzEyebrow">CONSTRUIR · ${game.step+1} DE 2</span><h2>Una palabra encuentra su forma.</h2><p>Arma la escritura de <b>${w.latin}</b>, ${w.meaning.toLowerCase()}. Empieza por el espacio de la derecha.</p><article class="pzRound"><div class="pzBuildTarget"><strong>${w.meaning}</strong></div><div class="pzBuildSlots" role="group" aria-label="Palabra en construcción, de derecha a izquierda">${w.letters.map((_,i)=>`<span class="pzBuildSlot pzHeb" lang="he" aria-label="Posición ${i+1}${game.slots[i]!==undefined?', '+game.options[game.slots[i]]:', vacía'}">${game.slots[i]!==undefined?game.options[game.slots[i]]:'·'}</span>`).join('')}</div><div class="pzBuildBank" aria-label="Letras disponibles">${game.options.map((l,i)=>`<button class="pzTile pzHeb" lang="he" data-pz="tile:${i}" ${game.slots.includes(i)||game.feedback&&!game.wrong?'disabled':''} aria-label="Añadir letra ${l}">${l}</button>`).join('')}</div><div class="pzActions">${btn('Deshacer','build-undo','ghost')}${btn('Comprobar','build-check')}</div><button class="pzTextButton" data-pz="build-hint">Ver una ayuda</button>${game.hint?`<div class="pzNotice">Mira la escritura <span class="pzHeb" lang="he" style="font-size:1.7em">${w.bare}</span>. ${w.id==='mayim'?'Recuerda usar mem final al terminar.':'La lectura o se apoya en la vav de esta palabra.'}</div>`:''}${game.feedback?`<div class="pzFeedback ${game.wrong?'warm':''}" id="pzFeedback" tabindex="-1" role="status"><b>${game.wrong?'Mira otra vez las letras.':'La palabra ya está aquí.'}</b><p>${game.wrong?`Compara tu construcción con ${w.bare}. Puedes deshacer y volver a intentarlo.`:`${w.vocalized} · ${w.latin} · ${w.meaning}. ${w.grammar}`}</p></div>${!game.wrong?`<div class="pzActions">${btn(game.step===0?'Otra palabra →':'Terminar ✓','build-next')}</div>`:''}`:''}</article><p class="pzCaption">Al construir usamos las letras sin vocalización. Después volvemos a observar la palabra vocalizada.</p>`,{title:'Construir palabras'})}

 function memoryLevels(){
  const suggested=C.memoryLevels.findIndex((_,i)=>!data.memory.completed.includes(i)),nextLevel=suggested<0?C.memoryLevels.length-1:suggested;
  layout(`<button class="pzTextButton" data-pz="home">← Mi taller</button><span class="pzEyebrow">EL ESPEJO DEL RECUERDO · 8 NIVELES</span><h2>Una letra encuentra su nombre.</h2><p>Empieza con cuatro parejas. Conoce las formas antes de jugar y avanza hasta recorrer las 22 letras del alfabeto hebreo y sus cinco formas finales.</p><div class="pzNotice">Puedes repetir o elegir cualquier nivel, sin cronómetro. Los niveles completados se guardan en este navegador; un tablero sin terminar comienza de nuevo al cerrar o recargar.</div><div class="pzRoundMeta"><span>${data.memory.completed.length} de ${C.memoryLevels.length} niveles completados</span></div><div class="pzActions">${btn('Continuar por el nivel '+(nextLevel+1)+' →','memory-level:'+nextLevel)}</div><div class="pzGrid">${C.memoryLevels.map((level,i)=>`<button type="button" class="pzCard" data-pz="memory-level:${i}"><span class="pzCardNum">NIVEL ${i+1} · ${level.review?'7 RONDAS':level.ids.length+' PAREJAS'}</span><h3>${level.title}</h3><p>${level.review?'Las 22 letras y las cinco formas finales en grupos pequeños.':level.ids.map(id=>ML(id).name).join(' · ')}</p><span class="pzCardFoot">${data.memory.completed.includes(i)?'Completado · volver a practicar':i===nextLevel?'Siguiente paso sugerido':'Explorar este nivel'} <span aria-hidden="true">↗</span></span></button>`).join('')}</div><p class="pzCaption">Aprendemos nombres y formas de imprenta. Los nombres se transliteran al español; pueden escribirse de otras maneras. Las variantes de pronunciación no agregan letras al alfabeto.</p>`,{title:'Niveles del Espejo'});
 }
 function startMemory(level=0,round=0,order=null){
  if(!Number.isInteger(level)||level<0||level>=C.memoryLevels.length)return;
  if(memoryTimer){clearTimeout(memoryTimer);memoryTimer=null}
  const config=C.memoryLevels[level],ids=order||(config.review?shuffle(C.memoryAlphabet.map(l=>l.id)):[...config.ids]),rounds=config.review?Math.ceil(ids.length/4):1;
  if(!Number.isInteger(round)||round<0||round>=rounds)return;
  const chosen=(config.review?ids.slice(round*4,round*4+4):ids).map(ML);
  data.memory.last=level;save();
  game={mode:'memory',level,round,rounds,order:ids,chosen,cards:shuffle(chosen.flatMap(l=>[{id:l.id,kind:'glyph',text:l.glyph},{id:l.id,kind:'name',text:l.name}])),open:[],matched:[],moves:0,busy:false};
  open('memory-study');
 }
 function memoryStudy(){
  if(game?.mode!=='memory'){open('memory-levels');return}
  const level=C.memoryLevels[game.level];
  layout(`<button class="pzTextButton" data-pz-view="memory-levels">← Elegir nivel</button><span class="pzEyebrow">NIVEL ${game.level+1}${game.rounds>1?' · RONDA '+(game.round+1)+' DE '+game.rounds:''}</span><h2>${level.title}</h2><p>${level.tip}</p><h3>Conoce las parejas antes de jugar</h3><div class="pzMemoryStudy">${game.chosen.map(l=>`<article><span class="pzHeb" lang="he">${l.glyph}</span><b>${l.name}</b>${l.base?`<small>Forma final de ${ML(l.base).glyph} · ${ML(l.base).name}</small>`:''}</article>`).join('')}</div><p>Observa cada letra junto a su nombre. Cuando quieras, ocultaremos las cartas para que encuentres las parejas.</p><div class="pzActions">${btn('Estoy listo para jugar →','memory-play')}</div><p class="pzCaption">Puedes volver a esta vista durante el juego. Consultarla no suma intentos ni completa el nivel.</p>`,{title:'Preparar nivel '+(game.level+1)});
 }
 function memory(){
  if(game?.mode!=='memory'){open('memory-levels');return}
  const size=game.chosen.length,finished=game.matched.length===size,lastRound=game.round===game.rounds-1;
  layout(`<button class="pzTextButton" data-pz-view="memory-levels">← Elegir nivel</button><span class="pzEyebrow">NIVEL ${game.level+1} · ${C.memoryLevels[game.level].title}${game.rounds>1?' · RONDA '+(game.round+1)+' DE '+game.rounds:''}</span><h2>El espejo del recuerdo.</h2><p>Abre dos cartas. Busca cada letra y su nombre. Puedes tomarte todo el tiempo que quieras.</p><div class="pzRoundMeta"><span>${game.matched.length} / ${size} parejas</span><span>${game.moves} encuentros</span></div><div class="pzMemory">${game.cards.map((c,i)=>{const matched=game.matched.includes(c.id),face=matched||game.open.includes(i);return `<button class="pzMemoryCard ${face?'face':''} ${matched?'matched':''}" data-pz="flip:${i}" aria-label="${face?(c.kind==='name'?c.text:'Letra '+ML(c.id).name):'Carta '+(i+1)+' por descubrir'}" ${matched?'disabled':''}>${face?`<span ${c.kind==='glyph'?'class="pzHeb" lang="he"':''}>${c.text}</span>`:'<span class="pzBack" aria-hidden="true">◈</span>'}</button>`}).join('')}</div>${finished?`<div class="pzFeedback" role="status">Encontraste las ${size} parejas.${lastRound?' Puedes guardar este nivel.':' Continúa con las siguientes letras del repaso.'}</div><div class="pzActions">${lastRound?btn('Guardar este nivel ✓','memory-finish'):btn('Siguiente ronda →','memory-next-round')}</div>`:`<div class="pzActions">${btn('Consultar las parejas','memory-help','alt')}${btn('Mezclar de nuevo','memory-restart','ghost')}</div>`}<p class="pzCaption">Los niveles registran tu práctica de reconocimiento; no son una evaluación de tu memoria general.</p>`,{title:'El espejo del recuerdo'});
 }
 function memoryDone(){
  if(lastResult?.mode!=='memory'||!Number.isInteger(lastResult.level)){open('memory-levels');return}
  const level=lastResult.level;
  layout(`<article class="pzSummary"><span class="pzEyebrow">NIVEL ${level+1} GUARDADO</span><h2>${C.memoryLevels[level].review?'Recorriste el alfabeto completo.':'Un nuevo grupo de letras tiene nombre.'}</h2><p>${C.memoryLevels[level].review?'Reconociste las 22 letras y las cinco formas finales en las siete rondas de este repaso.':'Encontraste las '+lastResult.total+' parejas de este nivel. Puedes repetirlas otro día o seguir con un nuevo grupo.'}</p><p>${data.memory.completed.length} de ${C.memoryLevels.length} niveles completados. El avance queda en este navegador y dispositivo.</p><div class="pzActions">${level<C.memoryLevels.length-1?btn('Explorar el nivel '+(level+2)+' →','memory-level:'+(level+1)):''}${btn('Ver todos los niveles','memory-levels','alt')}${btn('Volver al taller','home','alt')}</div></article>`,{title:'Nivel completado'});
 }
 function flip(index){
  if(game?.mode!=='memory'||!Number.isInteger(index)||game.busy||game.open.includes(index)||game.matched.includes(game.cards[index]?.id)||!game.cards[index])return;
  game.open.push(index);let matched=false;
  if(game.open.length===2){game.moves++;const [a,b]=game.open.map(i=>game.cards[i]);if(a.id===b.id){game.matched.push(a.id);game.open=[];matched=true}else game.busy=true}
  memory();if(matched)announce('Encontraste una pareja.');
  if(game.busy){const snapshot=game;memoryTimer=setTimeout(()=>{memoryTimer=null;if(game!==snapshot)return;game.open=[];game.busy=false;if(view==='memory')memory()},1100)}
 }
 function trace(){const l=C.letters[selectedLetter];layout(`<button class="pzTextButton" data-pz="letters">← Las letras</button><span class="pzEyebrow">TRAZO LIBRE · ${l.name.toUpperCase()}</span><h2>El dedo también aprende a mirar.</h2><p>Sigue la forma con el dedo, lápiz digital o ratón. Para desplazarte cuando amplíes la página, toca «Mover pantalla». Toca «Dibujar» para continuar.</p><div class="pzLetterTabs" aria-label="Elegir letra para trazar">${C.letters.map((x,i)=>`<button data-pz="trace-letter:${i}" aria-pressed="${i===selectedLetter}"><span class="pzHeb" lang="he">${x.glyph}</span><small>${x.name}</small></button>`).join('')}</div><div class="pzTraceTools" id="pzTraceTools" role="group" aria-label="Controles del trazado"><span id="pzTraceModeStatus" role="status"></span><div><button type="button" class="pzButton" id="pzTraceMode" data-pz="trace-mode">Mover pantalla</button><button type="button" class="pzButton alt" data-pz="letters">Salir del trazo</button></div></div><div class="pzTraceBox"><svg id="pzTrace" viewBox="0 0 360 270" role="img" aria-label="Guía de trazado de ${l.name}. Puedes dibujar con el dedo o estudiar visualmente su forma."><line class="pzTraceGuide" x1="20" y1="220" x2="340" y2="220"/><text x="180" y="218" text-anchor="middle" lang="he">${l.glyph}</text><g id="pzInk"></g></svg></div><div class="pzActions">${btn('Deshacer trazo','trace-undo','ghost')}${btn('Limpiar','trace-clear','ghost')}${btn('He practicado esta forma ✓','trace-finish')}</div><div class="pzNotice">${l.look} Esta guía usa letra de imprenta y no enseña caligrafía ritual de escriba. Puedes observar sin dibujar; no evaluamos automáticamente la precisión del trazo.</div>`,{title:'Trazar '+l.name});drawStrokes();updateTraceMode()}
 function drawStrokes(){const ink=document.getElementById('pzInk');if(ink)ink.innerHTML=traceStrokes.map(points=>`<polyline points="${points.map(p=>p.join(',')).join(' ')}"/>`).join('')}
 function startRead(index=0){game={mode:'read',index,order:index===1?[1,0]:[0,1],step:0,selected:null,revealed:false,correct:0,total:0};open('read')}
 function read(){if(game?.mode!=='read'){startRead();return}const w=C.words[game.index];layout(`<button class="pzTextButton" data-pz="words">← Las palabras</button><span class="pzEyebrow">EL TEXTO · ${game.step+1} DE 2 · ${w.ref}</span><h2>Encuentra ${w.latin} en el pasaje.</h2><p>${w.id==='mayim'?'Busca la palabra que significa las aguas: הַמָּיִם. Reconoce מים dentro de ella; הַ es el artículo definido.':'La palabra luz aparece más de una vez. Puedes tocar cualquiera de sus apariciones.'}</p><article class="pzRound"><div class="pzVerse" role="group" aria-label="Pasaje hebreo, de derecha a izquierda">${w.passage.map((t,i)=>`<button class="pzHeb ${game.revealed&&(i===w.target||i===w.alsoTarget)?'correct':game.selected===i?'wrong':''}" lang="he" data-pz="read-answer:${i}" ${game.revealed?'disabled':''}>${t}</button>`).join('')}</div>${game.selected!==null?`<div class="pzFeedback ${game.revealed?'':'warm'}" id="pzFeedback" tabindex="-1" role="status"><b>${game.revealed?'La palabra volvió a encontrarte.':'Busca las letras que ya conoces.'}</b><p>${game.revealed?w.context:`Recuerda la forma ${w.vocalized}. Puedes volver a intentarlo.`}</p>${link(w.source,w.ref)}</div>`:''}${game.revealed?`<p style="margin-top:20px">${w.translation}</p><div class="pzActions">${btn(game.step===0?'Otro pasaje →':'Terminar el encuentro ✓','read-next')}${game.step===0?btn('Volver al primer encuentro','welcome','alt'):''}</div>`:''}</article><p class="pzCaption">Los pasajes y las traducciones de trabajo se conservan como aparecen en los encuentros OR y RAKIA de Dérej.</p>`,{title:'Dentro del pasaje'})}
 function voices(){layout(`<span class="pzEyebrow">LAS VOCES DE NUESTROS CAMINOS</span><h2>Detrás de un nombre.</h2><p>Relaciona el nombre que encuentras en nuestros estudios con la persona y su obra.</p><div class="pzGrid">${C.sages.map(s=>`<article class="pzCard"><span class="pzEyebrow">${s.work}</span><h3>${s.name}</h3><p><b>${s.full}</b></p><p>${s.context}</p><button type="button" class="pzButton alt" data-voces-author="${s.source}">Conocer su vida y su obra →</button></article>`).join('')}</div><div class="pzActions">${btn('Relacionar los nombres →','activity:sages')}</div>`,{title:'Las voces'})}
 function progress(){const records=Object.values(data.records),known=records.filter(remembered).length,days=new Set(data.sessions.map(s=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago'}).format(new Date(s.at)))).size;layout(`<span class="pzEyebrow">VOLVER DEJA UNA HUELLA</span><h2>Tu avance en el Pozo.</h2><p>Cada encuentro cuenta. Aquí miramos lo que has practicado, sin compararte con otras personas.</p><div class="pzStats"><div class="pzStat"><strong>${data.seen.length}</strong><span>de 7 formas exploradas</span></div><div class="pzStat"><strong>${data.sessions.length}</strong><span>prácticas completadas</span></div><div class="pzStat"><strong>${days}</strong><span>días con encuentros</span></div></div>${data.session?`<div class="pzNotice">Hay una práctica pendiente. Puedes retomarla donde quedaste.<div class="pzActions">${btn('Retomar →','resume')}</div></div>`:''}<div class="pzNotice">El espejo del recuerdo: ${data.memory.completed.length} de ${C.memoryLevels.length} niveles completados.<div class="pzActions">${btn('Ver los niveles →','memory-levels')}</div></div><h3>Tu recorrido</h3>${activities.map(([id,title])=>`<div class="pzRecord"><span>${title}</span><span>${data.completed[id]?'Lo he practicado':'Por descubrir'}</span></div>`).join('')}<div class="pzNotice">${known} conexiones reconocidas en al menos tres días diferentes, con última respuesta acertada. Este dato describe tu práctica aquí; no es una evaluación de memoria general.</div><div class="pzActions">${btn('Mi práctica de hoy →','activity:daily')}${btn('Volver al taller','home','alt')}</div><p class="pzCaption" style="margin-top:24px">${storage?'El avance pertenece a este navegador. No se sincroniza todavía con otros dispositivos.':'El navegador no permite guardar. Descarga una copia antes de cerrar.'}</p><div class="pzActions"><button class="pzTextButton" data-pz="export">Descargar mi avance ↓</button><button class="pzTextButton" data-pz-view="sources">Cómo funciona el repaso</button></div>`,{title:'Mi avance'})}
 function sources(){layout(`<span class="pzEyebrow">MATERIAL DE ESTUDIO DÉREJ</span><h2>Nuestro material, aquí mismo.</h2><p>Las fichas, explicaciones y ejercicios del Pozo se desarrollan para Dérej, a partir de nuestros estudios. Puedes consultar todo sin salir del Camino.</p><ul class="pzSources">${C.sources.map(s=>`<li>${link(s.id,s.label)}</li>`).join('')}</ul><div class="pzReadingBox"><h3>Cómo construimos cada encuentro</h3><p>Partimos de una referencia bíblica o una enseñanza identificada. Escribimos una explicación didáctica propia, proponemos una práctica y dejamos espacio para tu reflexión. Las referencias bíblicas y los nombres de los autores se conservan para situar lo que aprendemos.</p><h3>Cómo regresan las preguntas</h3><p>La práctica diaria prioriza errores y preguntas pendientes. Un acierto propone volver en 1, 3 o 7 días según los días distintos con aciertos. Repetir muchas veces el mismo día no aumenta ese intervalo.</p><h3>La voz y el trazo</h3><p>El audio usa una voz hebrea del dispositivo, cuando existe. Es síntesis, no una grabación docente. El trazado permite explorar la forma; no detecta ni califica caligrafía.</p><h3>Un registro de aprendizaje</h3><p>Las cifras muestran tu práctica dentro de Dérej. No medimos neuroplasticidad ni prometemos beneficios clínicos.</p></div><p class="pzSourceNote">Primera unidad · Agua y luz. Las lecturas e interpretaciones se identifican por su naturaleza: texto bíblico, explicación didáctica o reflexión personal.</p>`,{title:'Nuestro material'})}
 function material(){
  const w=C.words.find(x=>x.source===materialId),sage=C.sages.find(x=>x.source===materialId),n=C.noaj.find(x=>x.source===materialId);
  let title='',body='';
  if(materialId==='alfabeto'){
   title='Las letras de Agua y luz';
   body=`<p>Estas seis letras y una forma final nos permiten empezar a distinguir el hebreo de las palabras que aparecen en nuestros estudios. Una letra se aprende mirando su forma, reconociendo su nombre y encontrándola dentro de una palabra.</p><div class="pzGrid">${C.letters.map(l=>`<article class="pzCard"><span class="pzHeb" lang="he" style="font-size:3em">${l.glyph}</span><h3>${l.name}</h3><p>${l.sound}</p><p>${l.look}</p><p class="pzCaption">Valor numérico: ${l.value}</p></article>`).join('')}</div><div class="pzNotice">Mem final, ם, es la forma de מ que usamos al final de una palabra; no agrega una letra al alfabeto. Los valores numéricos se estudian como una propiedad tradicional y no sustituyen la lectura.</div>`;
  }else if(materialId==='lectura'){
   title='Leer una palabra hebrea';
   body=`<article class="pzReadingBox"><h3>Primero, las letras</h3><p>El hebreo se lee de derecha a izquierda. Observa <span class="pzHeb" lang="he">מים</span>: mem, yod y mem final. Al construirla, la primera letra ocupa el espacio de la derecha.</p><h3>Después, la vocalización</h3><p>En <span class="pzHeb" lang="he">מַיִם</span>, los signos bajo las letras ayudan a leer máyim. En <span class="pzHeb" lang="he">אוֹר</span>, el punto junto a la vav acompaña el sonido o. La transliteración es una ayuda aproximada; no reemplaza escuchar la palabra.</p><h3>Volver al texto</h3><p>En un rollo de la Torá los signos vocálicos no están escritos. Empezamos con las ayudas visibles y aprendemos a reconocer la misma palabra sin ellas. El contexto y la tradición de lectura también importan.</p><h3>Comprender antes de interpretar</h3><p>Distinguimos lo que significa una palabra en su pasaje de las asociaciones simbólicas y de lo que ese texto despierta en cada persona. Las tres experiencias pueden acompañarse sin confundirse.</p></article>`;
  }else if(w){
   title=w.ref+' · '+w.latin;
   body=`<article class="pzReadingBox"><span class="pzEyebrow">TEXTO BÍBLICO · FRAGMENTO DE ESTUDIO</span><span class="pzHeb" lang="he" style="font-size:2em">${w.passage.join(' ')}</span><p>${w.translation}</p><p class="pzCaption">${w.ref} · traducción de trabajo usada en los encuentros de Dérej.</p></article><article class="pzReadingBox"><span class="pzEyebrow">EXPLICACIÓN DIDÁCTICA DÉREJ</span><h3>${w.vocalized} · ${w.meaning}</h3><p>${w.grammar}</p><p>${w.vowelNote}</p><p>${w.context}</p></article><article class="pzReadingBox"><span class="pzEyebrow">UNA REFLEXIÓN PARA EL CAMINO</span><p>${w.symbol}</p></article>`;
  }else if(sage){
   title=sage.name+' · '+sage.full;
   body=`<article class="pzReadingBox"><span class="pzEyebrow">NOMBRE Y OBRA</span><h3>${sage.name}</h3><p><b>${sage.full}</b></p><p>Obra que encontramos en nuestros Caminos: <b>${sage.work}</b>.</p><p>${sage.context}</p></article><article class="pzReadingBox"><span class="pzEyebrow">CÓMO ESTUDIAMOS EN DÉREJ</span><p>Relacionar un nombre conocido con su nombre completo nos ayuda a reconocer quién está hablando en el estudio. Las formas de escribir un nombre pueden variar al pasar del hebreo al español.</p><p>Esta ficha es una presentación didáctica propia. Cuando trabajamos una enseñanza concreta, conservamos el nombre de la obra y su referencia; una síntesis de Dérej se distingue de una cita literal del autor.</p></article>`;
  }else if(n){
   title=n.ref+' · Huellas de Nóaj';
   const context={
    'genesis-6-14':'Nóaj recibe una instrucción concreta: construir un arca. En el encuentro TEVA, Dérej invita a pensar qué necesita protección y qué límites ayudan a cuidar la vida.',
    'genesis-8-11':'La paloma regresa con una hoja de olivo. Nóaj reconoce una señal de que las aguas han disminuido. En la práctica de lectura distinguimos la señal narrada de la esperanza que puede despertar en nosotros.',
    'genesis-9-12':'El relato presenta el arco en las nubes como señal del pacto con los seres vivientes. El encuentro BRIT de Dérej abre una conversación sobre la responsabilidad y los vínculos que queremos sostener.',
    'genesis-8-1':'El relato dice que Dios recuerda a Nóaj y hace pasar un viento sobre la tierra. Las aguas disminuyen. Al estudiar, observamos esa secuencia antes de conversar sobre los nuevos comienzos.'
   };
   body=`<article class="pzReadingBox"><span class="pzEyebrow">${n.ref} · RESUMEN DE ESTUDIO DÉREJ</span><h3>${n.q}</h3><p><b>${n.a[0]}.</b> ${n.why}</p><p>${context[materialId]}</p><p class="pzCaption">Este texto es un resumen didáctico propio, no una cita literal del pasaje ni de un comentarista.</p></article>`;
  }else{title='Material de estudio';body='<p>Elige una ficha de nuestro material para continuar.</p>'}
  layout(`<button class="pzTextButton" data-pz="material-back">← Volver a donde estaba</button><span class="pzEyebrow">FICHA INTERNA · DÉREJ</span><h2>${esc(title)}</h2>${body}<div class="pzActions">${btn('Volver a mi ejercicio','material-back')}${btn('Ver nuestro material','material-list','alt')}</div>`,{title});
 }
 function refreshVoices(){if(!('speechSynthesis'in window)){voiceStatus='Este navegador no tiene lectura por voz. Puedes seguir con las fichas escritas.'}else{const voices=window.speechSynthesis.getVoices(),he=voices.some(v=>/^he(?:-|$)|^iw(?:-|$)/i.test(v.lang));voiceStatus=he?'Voz hebrea sintetizada del dispositivo. La transliteración en español es aproximada.':'Si tu dispositivo no ofrece una voz hebrea, esta actividad continúa en forma escrita.'}root.querySelectorAll('[data-voice-status]').forEach(el=>el.textContent=voiceStatus)}
 function speak(id){const target=C.letters.find(l=>l.id===id)||C.words.find(w=>w.id===id);if(!target)return;if(!('speechSynthesis'in window)){announce('Este navegador no ofrece reproducción por voz.');return}const voice=window.speechSynthesis.getVoices().find(v=>/^he(?:-|$)|^iw(?:-|$)/i.test(v.lang));if(!voice){announce('No hay una voz hebrea disponible en este dispositivo. Puedes continuar con la lectura y las fichas.');return}const u=new SpeechSynthesisUtterance(target.hebrewName||target.audio);u.voice=voice;u.lang=voice.lang;u.rate=.72;u.onerror=()=>announce('No se pudo reproducir la voz. Puedes continuar en forma escrita.');window.speechSynthesis.cancel();window.speechSynthesis.speak(u)}
 function activity(mode){if(mode==='build'){startBuild();return}if(mode==='memory'){open('memory-levels');return}if(mode==='trace'){traceDrawingEnabled=true;traceStrokes=[];open('trace');return}if(mode==='read'){startRead();return}if(data.session){layout(`<span class="pzEyebrow">HAY UN ENCUENTRO PENDIENTE</span><h2>Tu lugar te espera.</h2><p>Puedes retomar tu práctica o empezar una nueva. Las respuestas ya registradas conservan su avance.</p><div class="pzActions">${btn('Retomar','resume')}${btn('Empezar otra','replace:'+mode,'alt')}</div>`,{title:'Retomar'});return}startRound(mode)}
 function handle(action){const [name,arg]=action.split(':');
  if(name==='material'){materialBack=view;materialId=arg;open('material');return}
  if(name==='material-back'){open(materialBack);return}
  if(name==='material-list'){open('sources');return}
  if(['home','welcome','letters','words','progress','voices'].includes(name)){open(name);return}
  if(name==='discover'){data.discovered=true;save();document.querySelector('.pozoHotspot')?.classList.add('discovered');open('home');return}
  if(name==='large'||name==='contrast'){data.settings[name]=!data.settings[name];save();open(view,false);return}
  if(name==='welcome-letter'){selectedLetter=C.letters.findIndex(l=>l.id==='mem');open('letters');return}
  if(name==='letter'){selectedLetter=Math.max(0,Math.min(C.letters.length-1,Number(arg)||0));open('letters');return}
  if(name==='word'){selectedWord=Math.max(0,Math.min(1,Number(arg)||0));open('word');return}
  if(name==='speak'){speak(arg);return}
  if(name==='activity'){activity(arg);return}
  if(name==='replace'){data.session=null;startRound(arg);return}
  if(name==='resume'){open('round');return}
  if(name==='pause'){save();open('home');return}
  if(name==='answer'){respond(Number(arg));return}
  if(name==='hint'){const e=data.session?.entries[data.session.index];if(e){e.hint=!e.hint;save();round()}return}
  if(name==='next'){next();return}
  if(name==='build-word'){startBuild(Number(arg));return}
  if(name==='tile'&&game?.mode==='build'&&!game.feedback){const n=Number(arg),w=C.words[game.index];if(n>=0&&n<game.options.length&&!game.slots.includes(n)&&game.slots.length<w.letters.length){game.slots.push(n);build()}return}
  if(name==='build-undo'&&game?.mode==='build'){game.slots.pop();game.feedback=false;game.wrong=false;build();return}
  if(name==='build-hint'&&game?.mode==='build'){game.hint=!game.hint;build();return}
  if(name==='build-check'&&game?.mode==='build'){const w=C.words[game.index];if(game.feedback&&!game.wrong)return;if(game.slots.length!==w.letters.length){announce('Completa los tres espacios para comprobar la palabra.');return}game.attempts++;game.wrong=game.slots.map(i=>game.options[i]).join('')!==w.bare;game.feedback=true;if(!game.wrong)game.correct++;build();document.getElementById('pzFeedback')?.focus();return}
  if(name==='build-next'&&game?.mode==='build'&&game.feedback&&!game.wrong){if(game.step===0){game.step=1;game.index=game.order[1];game.slots=[];game.feedback=false;game.wrong=false;game.hint=false;game.options=shuffle([...C.words[game.index].letters,'ד','ו']);open('build')}else{complete('build',game.correct,game.attempts);lastResult={mode:'build',correct:game.correct,total:game.attempts};game=null;open('summary')}return}
  if(name==='flip'){flip(Number(arg));return}
  if(name==='memory-levels'){open('memory-levels');return}
  if(name==='memory-level'){startMemory(Number(arg));return}
  if(name==='memory-play'&&game?.mode==='memory'){open('memory');return}
  if(name==='memory-help'&&game?.mode==='memory'){game.open=[];game.busy=false;open('memory-study');return}
  if(name==='memory-restart'&&game?.mode==='memory'){startMemory(game.level,game.round,game.order);return}
  if(name==='memory-next-round'&&game?.mode==='memory'&&game.matched.length===game.chosen.length&&game.round<game.rounds-1){startMemory(game.level,game.round+1,game.order);return}
  if(name==='memory-finish'&&game?.mode==='memory'&&game.matched.length===game.chosen.length&&game.round===game.rounds-1){const level=game.level,total=game.order.length;if(!data.memory.completed.includes(level))data.memory.completed.push(level);complete('memory');lastResult={mode:'memory',correct:null,total,level};game=null;open('memory-done');return}
  if(name==='trace-mode'){traceDrawingEnabled=!traceDrawingEnabled;drawing=null;updateTraceMode();return}
  if(name==='trace'||name==='trace-letter'){traceDrawingEnabled=true;if(arg!==undefined)selectedLetter=Math.max(0,Math.min(C.letters.length-1,Number(arg)||0));traceStrokes=[];open('trace');return}
  if(name==='trace-undo'){traceStrokes.pop();drawStrokes();return}
  if(name==='trace-clear'){traceStrokes=[];drawStrokes();return}
  if(name==='trace-finish'){seen(C.letters[selectedLetter].id);complete('trace');lastResult={mode:'trace',correct:null,total:null};open('summary');return}
  if(name==='read-word'){startRead(Number(arg));return}
  if(name==='read-answer'&&game?.mode==='read'&&!game.revealed){const w=C.words[game.index],n=Number(arg);if(!Number.isInteger(n)||n<0||n>=w.passage.length)return;game.total++;game.selected=n;game.revealed=n===w.target||n===w.alsoTarget;if(game.revealed)game.correct++;read();document.getElementById('pzFeedback')?.focus();return}
  if(name==='read-next'&&game?.mode==='read'&&game.revealed){if(game.step===0){game.step=1;game.index=game.order[1];game.selected=null;game.revealed=false;open('read')}else{complete('read',game.correct,game.total);lastResult={mode:'read',correct:game.correct,total:game.total};game=null;open('summary')}return}
  if(name==='export'){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Derej-Pozo-Mi-Avance-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Tu copia de avance está lista para guardar.');return}
 }
 screen.addEventListener('click',e=>{const target=e.target.closest('[data-pz],[data-pz-view]');if(!target)return;if(target.dataset.pzView)open(target.dataset.pzView);else handle(target.dataset.pz)});
 screen.addEventListener('change',e=>{if(e.target.id==='pzNikud')root.querySelectorAll('[data-word-he]').forEach(el=>el.textContent=e.target.checked?C.words[el.dataset.wordHe].vocalized:C.words[el.dataset.wordHe].bare)});
 screen.addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();selectedLetter=e.key==='Home'?0:e.key==='End'?C.letters.length-1:(selectedLetter+(e.key==='ArrowRight'?1:-1)+C.letters.length)%C.letters.length;open('letters',false);document.getElementById('pzLetterTab'+selectedLetter)?.focus()});
 function tracePoint(e,svg){const r=svg.getBoundingClientRect();return [Math.round((e.clientX-r.left)/r.width*360),Math.round((e.clientY-r.top)/r.height*270)]}
 function beginTrace(svg,e,pointerId){drawing={pointerId,points:[tracePoint(e,svg)]};traceStrokes.push(drawing.points);drawStrokes()}

 function positionTraceTools(){
  const tools=document.getElementById('pzTraceTools');if(!tools||view!=='trace')return;
  const vv=window.visualViewport,scale=vv?.scale||1,width=vv?.width||window.innerWidth,height=vv?.height||window.innerHeight;
  tools.style.width=Math.max(180,Math.min(360,width*scale-24))+'px';
  tools.style.left=((vv?.offsetLeft||0)+width/2)+'px';
  tools.style.top=Math.max(0,(vv?.offsetTop||0)+height-(tools.offsetHeight+16)/scale)+'px';
  tools.style.transform='translateX(-50%) scale('+(1/scale)+')';
 }
 function updateTraceMode(){
  root.querySelector('.pzTraceBox')?.classList.toggle('pzTraceNavigate',!traceDrawingEnabled);
  const button=document.getElementById('pzTraceMode'),status=document.getElementById('pzTraceModeStatus');
  if(button)button.textContent=traceDrawingEnabled?'Mover pantalla':'Dibujar';
  if(status)status.textContent=traceDrawingEnabled?'Dibujo activo · puedes ampliar con dos dedos':'Puedes mover la página · tus trazos se conservan';
  positionTraceTools();
 }
 window.addEventListener('resize',positionTraceTools,{passive:true});
 if(window.visualViewport){window.visualViewport.addEventListener('resize',positionTraceTools,{passive:true});window.visualViewport.addEventListener('scroll',positionTraceTools,{passive:true})}
 screen.addEventListener('pointerdown',e=>{
  const svg=e.target.closest('#pzTrace');if(!svg||!traceDrawingEnabled)return;
  if(e.isPrimary===false){drawing=null;return}
  if(drawing||e.button!==0)return;
  if(e.pointerType!=='touch'&&e.cancelable)e.preventDefault();
  try{svg.setPointerCapture?.(e.pointerId)}catch{}beginTrace(svg,e,e.pointerId);
 },{passive:false});
 screen.addEventListener('pointermove',e=>{if(!traceDrawingEnabled||!drawing||drawing.pointerId!==e.pointerId)return;const svg=document.getElementById('pzTrace');if(!svg)return;if(e.pointerType!=='touch'&&e.cancelable)e.preventDefault();drawing.points.push(tracePoint(e,svg));drawStrokes()},{passive:false});
 ['pointerup','pointercancel','lostpointercapture'].forEach(type=>screen.addEventListener(type,e=>{if(drawing?.pointerId===e.pointerId)drawing=null}));
 // Un dedo dibuja; los gestos de varios dedos quedan libres para ampliar.
 // Con Pointer Events, touch-action resuelve el gesto sin cancelar el zoom nativo.
 screen.addEventListener('touchstart',e=>{
  const box=e.target.closest('.pzTraceBox'),svg=box?.querySelector('#pzTrace');if(!svg||!traceDrawingEnabled)return;
  if(e.touches.length!==1){drawing=null;return}
  if(!window.PointerEvent){if(e.cancelable)e.preventDefault();if(!drawing)beginTrace(svg,e.touches[0],'touch')}
 },{passive:false});
 screen.addEventListener('touchmove',e=>{
  const box=e.target.closest('.pzTraceBox');if(!box||!traceDrawingEnabled)return;
  if(e.touches.length!==1){drawing=null;return}
  if(!window.PointerEvent){if(e.cancelable)e.preventDefault();if(drawing?.pointerId==='touch'){const svg=box.querySelector('#pzTrace');if(svg){drawing.points.push(tracePoint(e.touches[0],svg));drawStrokes()}}}
 },{passive:false});
 ['touchend','touchcancel'].forEach(type=>screen.addEventListener(type,()=>{if(drawing?.pointerId==='touch')drawing=null}));
 screen.addEventListener('wheel',e=>{if(traceDrawingEnabled&&drawing&&!e.ctrlKey&&!e.metaKey&&e.target.closest('.pzTraceBox')&&e.cancelable)e.preventDefault()},{passive:false});
 screen.addEventListener('dragstart',e=>{if(traceDrawingEnabled&&e.target.closest('.pzTraceBox'))e.preventDefault()});
 if('speechSynthesis'in window)window.speechSynthesis.addEventListener?.('voiceschanged',refreshVoices);
 const previousRoute=route;
 route=function(name){previousRoute(name);if(name==='pozo')open('home');else if(drawing)drawing=null};
 if(data.discovered)document.querySelector('.pozoHotspot')?.classList.add('discovered');
 window.DEREJ_POZO={version:'1.0',open:()=>route('pozo')};
 if(location.hash==='#pozo')route('pozo');
})();
